style.css:
@-moz-document domain("music.youtube.com") {
ytmusic-app {
    /* swap any colors, wallpaper URL, or sizing below to tweak the vibe */
    --my-wallpaper: url("https://wallpapercave.com/wp/wp15432194.jpg");
    --my-wallpaper-size: min(560px, 44vw) auto;
    --my-wallpaper-pos: right 28px bottom 88px;
    --my-canvas: #ffffff;
    --my-surface: rgba(255, 250, 251, 0.84);
    --my-card: rgba(255, 248, 250, 0.86);
    --my-blush: #f7dce2;
    --my-blush-soft: #fdf2f5;
    --my-accent: #df8e9e;
    --my-accent-deep: #b85d70;
    --my-ink: #3d2c28;
    --my-ink-soft: #7a5c55;
    --my-border: rgba(223, 142, 158, 0.42);
    --my-radius: 16px;

    /* YouTube Music theme variables */
    --yt-spec-text-primary: var(--my-ink) !important;
    --yt-spec-text-secondary: var(--my-ink-soft) !important;
    --yt-spec-text-disabled: #a68b84 !important;
    --yt-spec-icon-active-other: var(--my-accent-deep) !important;
    --yt-spec-icon-inactive: var(--my-ink-soft) !important;
    --yt-spec-brand-background-primary: var(--my-surface) !important;
    --yt-spec-brand-background-solid: var(--my-canvas) !important;
    --yt-spec-general-background-a: var(--my-canvas) !important;
    --yt-spec-general-background-b: var(--my-blush-soft) !important;
    --yt-spec-badge-chip-background: var(--my-blush) !important;
    --yt-spec-10-percent-layer: rgba(223, 142, 158, 0.18) !important;
    --yt-endpoint-color: var(--my-ink) !important;
    --yt-endpoint-hover-color: var(--my-accent-deep) !important;
    --ytmusic-background: transparent !important;
    --ytmusic-nav-bar: var(--my-surface) !important;
    --ytmusic-player-bar: var(--my-surface) !important;
  }

  /* clear dark ambient backdrop & show Lopunny wallpaper */
  ytmusic-app::before {
    content: "" !important;
    position: fixed !important;
    inset: 0 !important;
    background-color: var(--my-canvas) !important;
    background-image: var(--my-wallpaper) !important;
    background-repeat: no-repeat !important;
    background-position: var(--my-wallpaper-pos) !important;
    background-size: var(--my-wallpaper-size) !important;
    pointer-events: none !important;
    z-index: 0 !important;
  }

  ytmusic-app,
  ytmusic-app-layout,
  #layout.ytmusic-app,
  ytmusic-browse-response,
  .background-gradient.ytmusic-browse-response {
    background: transparent !important;
    color: var(--my-ink) !important;
  }

  ytmusic-browse-response #background,
  ytmusic-fullbleed-thumbnail-renderer {
    opacity: 0 !important;
    background: transparent !important;
  }

  /* cocoa text, links & top-left Music logo */
  ytmusic-app a.yt-simple-endpoint,
  ytmusic-app yt-formatted-string,
  ytmusic-app .title.ytmusic-two-row-item-renderer,
  ytmusic-app .title.ytmusic-responsive-list-item-renderer,
  ytmusic-app .title.ytmusic-carousel-shelf-basic-header-renderer,
  ytmusic-app .title.ytmusic-player-bar {
    color: var(--my-ink) !important;
  }

  ytmusic-app .subtitle,
  ytmusic-app .byline,
  ytmusic-app .secondary-flex-columns yt-formatted-string,
  ytmusic-app .secondary-flex-columns a.yt-simple-endpoint {
    color: var(--my-ink-soft) !important;
  }

  ytmusic-logo svg path[fill="#FFFFFF"],
  ytmusic-logo svg path[fill="#fff"],
  ytmusic-nav-bar .logo svg path:not([fill="#FF0000"]):not([fill="#ff0000"]) {
    fill: var(--my-ink) !important;
  }

  /* frosted top bar, sidebar & buttons */
  ytmusic-nav-bar,
  #nav-bar-background.ytmusic-app-layout,
  ytmusic-guide-renderer,
  #guide-wrapper.ytmusic-app,
  div#mini-guide {
    background: var(--my-surface) !important;
    backdrop-filter: blur(12px) !important;
    border-color: var(--my-border) !important;
  }

  ytmusic-guide-entry-renderer[active] tp-yt-paper-item,
  ytmusic-guide-entry-renderer tp-yt-paper-item:hover {
    background: var(--my-blush) !important;
    border-radius: 999px !important;
  }

  ytmusic-guide-renderer button,
  ytmusic-carousel-shelf-basic-header-renderer button,
  ytmusic-carousel-shelf-basic-header-renderer a.yt-simple-endpoint {
    background: var(--my-blush) !important;
    color: var(--my-ink) !important;
    border: 1px solid var(--my-border) !important;
    border-radius: 999px !important;
  }

  ytmusic-search-box .search-box.ytmusic-search-box {
    background: var(--my-blush-soft) !important;
    border: 1px solid var(--my-border) !important;
    border-radius: 999px !important;
  }

  ytmusic-search-box input {
    color: var(--my-ink) !important;
  }

  /* clean pastel mood chips without dark outer capsules */
  ytmusic-chip-cloud-chip-renderer {
    background: transparent !important;
    border: none !important;
    box-shadow: none !important;
  }

  ytmusic-chip-cloud-chip-renderer a.ytmusic-chip-cloud-chip-renderer,
  ytmusic-pivot-bar-item-renderer {
    background: var(--my-blush) !important;
    color: var(--my-ink) !important;
    border: 1px solid var(--my-border) !important;
    border-radius: 999px !important;
    box-shadow: 0 2px 6px rgba(61, 44, 40, 0.06) !important;
  }

  ytmusic-chip-cloud-chip-renderer[chip-style="STYLE_PRIMARY"] a.ytmusic-chip-cloud-chip-renderer,
  ytmusic-pivot-bar-item-renderer.iron-selected {
    background: var(--my-accent) !important;
    color: #ffffff !important;
  }

  /* airy shelves & cute song cards */
  ytmusic-carousel-shelf-renderer,
  ytmusic-section-list-renderer {
    background: transparent !important;
  }

  ytmusic-responsive-list-item-renderer {
    background: var(--my-card) !important;
    border: 1px solid var(--my-border) !important;
    border-radius: var(--my-radius) !important;
    backdrop-filter: blur(8px) !important;
  }

  ytmusic-two-row-item-renderer img,
  ytmusic-responsive-list-item-renderer img,
  ytmusic-player-bar img {
    border-radius: 12px !important;
    box-shadow: 0 4px 12px rgba(61, 44, 40, 0.12) !important;
  }

  /* cute bottom player bar & now playing page */
  ytmusic-player-bar,
  #player-bar-background.ytmusic-app-layout {
    background: rgba(253, 242, 245, 0.92) !important;
    backdrop-filter: blur(14px) !important;
    border-top: 1px solid var(--my-border) !important;
  }

  #progress-bar.ytmusic-player-bar {
    --paper-slider-active-color: var(--my-accent-deep) !important;
    --paper-slider-knob-color: var(--my-accent-deep) !important;
    --paper-slider-knob-start-color: var(--my-accent-deep) !important;
    --paper-slider-container-color: var(--my-blush) !important;
  }

  ytmusic-player-page {
    background: rgba(255, 250, 251, 0.9) !important;
    backdrop-filter: blur(14px) !important;
  }
}
